-- Ejecutar después de cargar las tablas de datos.
ALTER TABLE programa_inversion ADD FOREIGN KEY(eps_id,cod_proyecto) REFERENCES proyecto_inversion(eps_id,cod_proyecto);
ALTER TABLE ejecucion_inversion ADD CONSTRAINT ejecucion_proyecto_fk
 FOREIGN KEY(eps_id,cod_proyecto) REFERENCES proyecto_inversion(eps_id,cod_proyecto);
ALTER TABLE programa_inversion ADD CHECK(monto_programado_original>=0 AND monto_programado_vigente>=0);
ALTER TABLE procedimiento_fuente ADD CHECK(monto_solicitado>=0 AND monto_aprobado>=0);
ALTER TABLE ejecucion_inversion ADD CHECK(avance_fisico_acumulado_pct BETWEEN 0 AND 100);
ALTER TABLE fondo_inversion ADD CHECK(uso_excepcional>=0 AND deposito_programado>=0);
ALTER TABLE meta_gestion ADD CHECK(cumplimiento_pct>=0);
CREATE INDEX hito_tramite ON hito(tramite_id,nro_hito);
CREATE INDEX programa_eps_proyecto ON programa_inversion(eps_id,cod_proyecto);
CREATE INDEX ejecucion_eps_proyecto ON ejecucion_inversion(eps_id,cod_proyecto);
ALTER TABLE catalogo_eps ADD UNIQUE(cod_eps);
ALTER TABLE localidad_eps ADD UNIQUE NULLS NOT DISTINCT(cod_eps,localidad,ubigeo);
ALTER TABLE procedimiento_fuente ADD UNIQUE(id_expediente);
ALTER TABLE hito ADD UNIQUE(id_expediente,nro_hito);
ALTER TABLE programa_inversion ADD UNIQUE NULLS NOT DISTINCT(cod_eps,periodo_regulatorio,cod_proyecto,anio);
ALTER TABLE ejecucion_inversion ADD UNIQUE(cod_eps,cod_proyecto,anio_trimestre);
ALTER TABLE fondo_inversion ADD UNIQUE(cod_eps,anio_mes,tipo_fondo);
ALTER TABLE estado_financiero ADD UNIQUE(cod_eps,anio);
ALTER TABLE meta_gestion ADD UNIQUE NULLS NOT DISTINCT(cod_eps,periodo_regulatorio,cod_meta,nivel,localidad,anio);
ALTER TABLE inversion_mef ADD UNIQUE(cui);
ALTER TABLE ipm ADD UNIQUE(anio_mes);
ALTER TABLE programa_inversion ADD COLUMN tramite_modificacion_id varchar(80);
UPDATE programa_inversion p SET tramite_modificacion_id=e.tramite_id FROM procedimiento_fuente e
 WHERE p.id_expediente_modificacion=e.id_expediente AND p.eps_id=e.eps_id;
ALTER TABLE programa_inversion ADD FOREIGN KEY(tramite_modificacion_id,eps_id) REFERENCES tramite(id,eps_id);
ALTER TABLE fondo_inversion ADD COLUMN tramite_uso_id varchar(80);
UPDATE fondo_inversion f SET tramite_uso_id=e.tramite_id FROM procedimiento_fuente e
 WHERE f.id_expediente_uso_excepcional=e.id_expediente AND f.eps_id=e.eps_id;
ALTER TABLE fondo_inversion ADD FOREIGN KEY(tramite_uso_id,eps_id) REFERENCES tramite(id,eps_id);
CREATE FUNCTION vincular_programa() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 SELECT e.tramite_id INTO NEW.tramite_modificacion_id FROM procedimiento_fuente e
 WHERE e.id_expediente=NEW.id_expediente_modificacion AND e.eps_id=NEW.eps_id;
 RETURN NEW;
END;
$$;
CREATE TRIGGER programa_vinculo BEFORE INSERT OR UPDATE ON programa_inversion
 FOR EACH ROW EXECUTE FUNCTION vincular_programa();
CREATE FUNCTION vincular_fondo() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 SELECT e.tramite_id INTO NEW.tramite_uso_id FROM procedimiento_fuente e
 WHERE e.id_expediente=NEW.id_expediente_uso_excepcional AND e.eps_id=NEW.eps_id;
 RETURN NEW;
END;
$$;
CREATE TRIGGER fondo_vinculo BEFORE INSERT OR UPDATE ON fondo_inversion
 FOR EACH ROW EXECUTE FUNCTION vincular_fondo();


-- FUENTE: 06_views.sql
-- Vistas de lectura. Ninguna publicación se habilita automáticamente.
CREATE OR REPLACE VIEW expedientes AS SELECT * FROM tramite;
CREATE OR REPLACE VIEW actuaciones AS SELECT * FROM actuacion;
CREATE OR REPLACE VIEW documentos AS SELECT * FROM documento;
CREATE OR REPLACE VIEW fuentes AS SELECT * FROM fuente;
CREATE OR REPLACE VIEW v_procedencia AS
 SELECT r.canonical_id,r.source_record_id,r.source_hash,r.lote_id,
 f.source_type,f.source_file,f.source_hash AS archivo_hash
 FROM registro_fuente r JOIN fuente f ON f.id=r.fuente_id WHERE r.presente;
CREATE OR REPLACE VIEW v_expediente_360 AS
 SELECT t.id,t.procedimiento,t.estado,t.etapa,t.eps_id,e.nombre AS eps,
 p.source_type,p.source_record_id,p.source_file,t.publicable,t.version
 FROM tramite t JOIN eps e ON e.id=t.eps_id JOIN v_procedencia p ON p.canonical_id=t.id;
CREATE OR REPLACE VIEW v_proyecto_ejecucion AS
 SELECT p.canonical_id AS programa_id,p.eps_id,p.cod_proyecto,p.anio,p.nombre_proyecto,
 p.monto_programado_vigente,p.poblacion_beneficiaria,x.anio_trimestre,
 x.ejecucion_financiera_acumulada,x.avance_fisico_acumulado_pct
 FROM programa_inversion p LEFT JOIN ejecucion_inversion x
 ON p.eps_id=x.eps_id AND p.cod_proyecto=x.cod_proyecto AND left(x.anio_trimestre,4)::integer=p.anio;
CREATE OR REPLACE VIEW v_colisiones_origen AS
 SELECT source_record_id,count(*) AS cantidad,array_agg(canonical_id) AS registros
 FROM registro_fuente GROUP BY source_record_id HAVING count(*)>1;


-- FUENTE: final/10_identidad_permisos.sql
-- Complemento del esquema operativo. Instalación NUEVA, sin usuarios de demostración.
BEGIN;
CREATE SCHEMA seguridad;
CREATE TABLE seguridad.rol (
 id varchar(30) PRIMARY KEY CHECK(id IN ('analista_srt','coordinacion_dre','jefatura_dre','eps')),
 nombre text NOT NULL, perfil text NOT NULL CHECK(perfil IN ('sunass','eps')),
 UNIQUE(id,perfil), CHECK((id='eps')=(perfil='eps'))
);
CREATE TABLE seguridad.permiso (
 id varchar(60) PRIMARY KEY, descripcion text NOT NULL
);
CREATE TABLE seguridad.rol_permiso (
 rol_id varchar(30) NOT NULL REFERENCES seguridad.rol(id),
 permiso_id varchar(60) NOT NULL REFERENCES seguridad.permiso(id),
 PRIMARY KEY(rol_id,permiso_id)
);
CREATE TABLE seguridad.vista (
 id varchar(30) PRIMARY KEY, nombre text NOT NULL,
 permiso_id varchar(60) NOT NULL REFERENCES seguridad.permiso(id)
);


 SELECT 'analista_srt',id FROM seguridad.permiso WHERE id IN
 ('expediente.consultar','trazabilidad.consultar','bandeja.consultar','alerta.consultar','ficha360.consultar',
  'agente.consultar','evaluacion.validar','requerimiento.registrar','respuesta.verificar','encargo.consultar','encargo.actualizar');
 SELECT 'coordinacion_dre',id FROM seguridad.permiso WHERE id IN
 ('expediente.consultar','trazabilidad.consultar','bandeja.consultar','alerta.consultar','ficha360.consultar','agente.consultar',
  'recepcion.gestionar','asignacion.gestionar','acto_externo.registrar','dashboard.consultar','reporte.consultar',
  'encargo.consultar','encargo.actualizar','encargo.gestionar','publicacion.gestionar');
 SELECT 'jefatura_dre',id FROM seguridad.permiso WHERE id!='eps.respuesta_informar';
 SELECT 'eps',id FROM seguridad.permiso WHERE id IN
 ('expediente.consultar','trazabilidad.consultar','agente.consultar','eps.respuesta_informar');


ALTER TABLE usuario ADD COLUMN rol_id varchar(30) NOT NULL;
ALTER TABLE usuario ADD COLUMN credenciales_version integer NOT NULL DEFAULT 1 CHECK(credenciales_version>0);
ALTER TABLE usuario ADD COLUMN creado timestamptz NOT NULL DEFAULT now();
ALTER TABLE usuario ADD CONSTRAINT usuario_rol_perfil_fk FOREIGN KEY(rol_id,perfil) REFERENCES seguridad.rol(id,perfil);
ALTER TABLE usuario ADD CONSTRAINT usuario_hash_seguro CHECK
 (password_hash IS NULL OR password_hash ~ '^scrypt\$[0-9a-f]{32}\$[0-9a-f]{128}$');
ALTER TABLE usuario ADD CONSTRAINT usuario_activo_con_credencial CHECK(NOT activo OR password_hash IS NOT NULL);

CREATE TABLE seguridad.sesion (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id varchar(80) NOT NULL REFERENCES usuario(id),
 refresh_hash varchar(64) NOT NULL UNIQUE CHECK(refresh_hash ~ '^[0-9a-f]{64}$'),
 credenciales_version integer NOT NULL CHECK(credenciales_version>0),
 creada timestamptz NOT NULL DEFAULT now(), vence timestamptz NOT NULL,
 revocada_en timestamptz, motivo_revocacion text, CHECK(vence>creada),
 CHECK(revocada_en IS NULL OR revocada_en>=creada)
);
CREATE INDEX sesion_usuario ON seguridad.sesion(usuario_id);
CREATE INDEX sesion_activa_vence ON seguridad.sesion(vence) WHERE revocada_en IS NULL;
CREATE TABLE seguridad.intento_acceso (
 clave_hash varchar(64) PRIMARY KEY CHECK(clave_hash ~ '^[0-9a-f]{64}$'),
 intentos integer NOT NULL CHECK(intentos>0), ventana_fin timestamptz NOT NULL
);
CREATE TABLE seguridad.evento_acceso (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id varchar(80) REFERENCES usuario(id),
 evento text NOT NULL CHECK(evento IN ('login_correcto','login_fallido','logout','renovacion','revocacion')),
 registrado timestamptz NOT NULL DEFAULT now(), detalle text
);

CREATE FUNCTION seguridad.revocar_por_cambio_usuario() RETURNS trigger
 LANGUAGE plpgsql SET search_path=pg_catalog,public,seguridad AS $$
BEGIN
 IF NEW.password_hash IS DISTINCT FROM OLD.password_hash OR NEW.rol_id IS DISTINCT FROM OLD.rol_id
    OR NEW.eps_id IS DISTINCT FROM OLD.eps_id OR NEW.activo IS DISTINCT FROM OLD.activo THEN
  NEW.credenciales_version=OLD.credenciales_version+1;
 END IF;
 IF NEW.credenciales_version IS DISTINCT FROM OLD.credenciales_version THEN
  UPDATE seguridad.sesion SET revocada_en=COALESCE(revocada_en,now()),motivo_revocacion='Cambio de cuenta o credenciales'
   WHERE usuario_id=OLD.id AND revocada_en IS NULL;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER usuario_revoca BEFORE UPDATE ON usuario FOR EACH ROW EXECUTE FUNCTION seguridad.revocar_por_cambio_usuario();

CREATE VIEW seguridad.v_usuario_permisos AS
 SELECT u.id AS usuario_id,u.rol_id,u.perfil,u.eps_id,rp.permiso_id
 FROM public.usuario u JOIN seguridad.rol_permiso rp ON rp.rol_id=u.rol_id WHERE u.activo;
CREATE VIEW seguridad.v_usuario_vistas AS
 SELECT DISTINCT p.usuario_id,v.id,v.nombre FROM seguridad.v_usuario_permisos p
 JOIN seguridad.vista v ON v.permiso_id=p.permiso_id
 WHERE (p.perfil='eps' AND v.id IN ('mis_tramites','trazabilidad','agente')) OR p.perfil='sunass';

CREATE FUNCTION seguridad.tiene_permiso(p_usuario text,p_permiso text) RETURNS boolean
 LANGUAGE sql STABLE SET search_path=pg_catalog,public,seguridad AS $$
 SELECT EXISTS(SELECT FROM seguridad.v_usuario_permisos WHERE usuario_id=p_usuario AND permiso_id=p_permiso)
$$;
CREATE FUNCTION seguridad.sesion_valida(p_sesion uuid) RETURNS boolean
 LANGUAGE sql STABLE SET search_path=pg_catalog,public,seguridad AS $$
 SELECT EXISTS(SELECT FROM seguridad.sesion s JOIN public.usuario u ON u.id=s.usuario_id
  WHERE s.id=p_sesion AND u.activo AND s.revocada_en IS NULL AND s.vence>now()
    AND s.credenciales_version=u.credenciales_version)
$$;
COMMIT;


-- FUENTE: final/20_trazabilidad_ambitos.sql
BEGIN;
CREATE TABLE procedimiento_portal (
 id text PRIMARY KEY CHECK(id IN ('CPI','UFI','RP')), nombre text NOT NULL
);
-- Los otros procedimientos del dataset permanecen en tramite y sus tablas fuente.
CREATE VIEW v_expedientes_portal AS
 SELECT t.* FROM tramite t JOIN procedimiento_portal p ON p.id=t.procedimiento
 JOIN registro_fuente r ON r.canonical_id=t.id WHERE r.presente;

CREATE TABLE asignacion_tramite (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 tramite_id varchar(80) NOT NULL REFERENCES tramite(id),
 usuario_id varchar(80) NOT NULL REFERENCES usuario(id),
 asignado_por varchar(80) NOT NULL REFERENCES usuario(id),
 inicio timestamptz NOT NULL DEFAULT now(), fin timestamptz, motivo text,
 CHECK(fin IS NULL OR fin>=inicio)
);
CREATE UNIQUE INDEX asignacion_activa_unica ON asignacion_tramite(tramite_id) WHERE fin IS NULL;
CREATE INDEX asignacion_usuario ON asignacion_tramite(usuario_id,tramite_id) WHERE fin IS NULL;
CREATE FUNCTION validar_asignacion_portal() RETURNS trigger LANGUAGE plpgsql
 SET search_path=pg_catalog,public,seguridad AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.tramite_id IS DISTINCT FROM OLD.tramite_id OR NEW.usuario_id IS DISTINCT FROM OLD.usuario_id
     OR NEW.asignado_por IS DISTINCT FROM OLD.asignado_por OR NEW.inicio IS DISTINCT FROM OLD.inicio
     OR OLD.fin IS NOT NULL THEN
   RAISE EXCEPTION 'La asignación histórica no se reemplaza; cerrar e insertar otra' USING ERRCODE='23514';
  END IF;
  -- Permite cerrar una asignación aunque el analista o asignador ya estén inactivos.
  IF NEW.fin IS NOT NULL THEN RETURN NEW; END IF;
 END IF;
 IF NOT EXISTS(SELECT FROM public.usuario WHERE id=NEW.usuario_id AND activo AND rol_id='analista_srt') THEN
  RAISE EXCEPTION 'La asignación requiere un analista SRT activo' USING ERRCODE='23514';
 END IF;
 IF NOT seguridad.tiene_permiso(NEW.asignado_por,'asignacion.gestionar') THEN
  RAISE EXCEPTION 'El asignador no tiene permiso' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT FROM public.v_expedientes_portal WHERE id=NEW.tramite_id) THEN
  RAISE EXCEPTION 'Expediente fuera de los tres procedimientos del portal' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER asignacion_valida BEFORE INSERT OR UPDATE ON asignacion_tramite
 FOR EACH ROW EXECUTE FUNCTION validar_asignacion_portal();

CREATE FUNCTION seguridad.puede_tramite(p_usuario text,p_tramite text,p_permiso text DEFAULT 'expediente.consultar')
 RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,public,seguridad AS $$
 SELECT EXISTS(SELECT FROM public.usuario u JOIN public.v_expedientes_portal t ON t.id=p_tramite
 WHERE u.id=p_usuario AND u.activo AND seguridad.tiene_permiso(u.id,p_permiso) AND
 ((u.rol_id IN ('coordinacion_dre','jefatura_dre')) OR
  (u.rol_id='analista_srt' AND EXISTS(SELECT FROM public.asignacion_tramite a
    WHERE a.tramite_id=t.id AND a.usuario_id=u.id AND a.fin IS NULL)) OR
  (u.rol_id='eps' AND u.eps_id=t.eps_id)))
$$;
CREATE FUNCTION seguridad.puede_documento(p_usuario text,p_documento text) RETURNS boolean
 LANGUAGE sql STABLE SET search_path=pg_catalog,public,seguridad AS $$
 SELECT EXISTS(SELECT FROM public.documento d JOIN public.usuario u ON u.id=p_usuario
 JOIN public.registro_fuente r ON r.canonical_id=d.id AND r.presente
 WHERE d.id=p_documento AND seguridad.puede_tramite(u.id,d.tramite_id)
 AND (u.perfil='sunass' OR d.visibilidad IN ('partes','publica')))
$$;
CREATE FUNCTION seguridad.documento_publicado(p_documento text) RETURNS boolean
 LANGUAGE sql STABLE SET search_path=pg_catalog,public,seguridad AS $$
 SELECT EXISTS(SELECT FROM public.documento d JOIN public.v_expedientes_portal t ON t.id=d.tramite_id
 JOIN public.publicacion p ON p.tramite_id=t.id JOIN public.registro_fuente r ON r.canonical_id=d.id
 WHERE d.id=p_documento AND d.visibilidad='publica' AND p.publicada AND t.publicable AND r.presente)
$$;

CREATE TABLE interviniente_documental (
 id text PRIMARY KEY, nombre text NOT NULL
);
ALTER TABLE actuacion ADD COLUMN interviniente_id text REFERENCES interviniente_documental(id);
COMMENT ON COLUMN actuacion.usuario_id IS 'Persona del portal que registra; no equivale al emisor del acto externo.';
COMMENT ON COLUMN actuacion.interviniente_id IS 'Área o actor acreditado por el documento; no concede acceso al portal.';

CREATE TABLE encargo (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tramite_id varchar(80) NOT NULL REFERENCES tramite(id),
 titulo text NOT NULL, responsable_interviniente text NOT NULL REFERENCES interviniente_documental(id),
 responsable_nombre text, fecha_limite date,
 estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','en_curso','hecho','cancelado')),
 documento_id varchar(120) NOT NULL, fecha_acreditada date NOT NULL,
 registrado_por varchar(80) NOT NULL REFERENCES usuario(id), version integer NOT NULL DEFAULT 1 CHECK(version>0),
 FOREIGN KEY(documento_id,tramite_id) REFERENCES documento(id,tramite_id)
);
CREATE INDEX encargo_tramite ON encargo(tramite_id,estado);
CREATE TABLE encargo_evento (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, encargo_id uuid NOT NULL REFERENCES encargo(id),
 estado text NOT NULL CHECK(estado IN ('pendiente','en_curso','hecho','cancelado')),
 documento_id varchar(120) NOT NULL REFERENCES documento(id), fecha_acreditada date NOT NULL,
 registrado_por varchar(80) NOT NULL REFERENCES usuario(id), registrado timestamptz NOT NULL DEFAULT now(), detalle text
);
CREATE FUNCTION validar_encargo_evento() RETURNS trigger LANGUAGE plpgsql
 SET search_path=pg_catalog,public,seguridad AS $$
BEGIN
 IF NOT EXISTS(SELECT FROM public.encargo e JOIN public.documento d ON d.tramite_id=e.tramite_id
  WHERE e.id=NEW.encargo_id AND d.id=NEW.documento_id) THEN
  RAISE EXCEPTION 'Evidencia de otro expediente' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER encargo_evento_valido BEFORE INSERT OR UPDATE ON encargo_evento
 FOR EACH ROW EXECUTE FUNCTION validar_encargo_evento();

CREATE VIEW v_trazabilidad_portal AS
 SELECT a.id,a.tramite_id,a.tipo,a.titulo,a.detalle,a.fecha_acreditada,a.fecha_por_validar,
 a.documento_id,a.fuente,a.verificada,a.estado_origen,a.estado_destino,a.paso_origen,a.paso_destino,
 a.usuario_id AS registrado_por,u.nombre_visible AS nombre_registrador,a.interviniente_id,
 i.nombre AS interviniente_documental,a.actor AS actor_fuente,a.registrado
 FROM actuacion a JOIN v_expedientes_portal t ON t.id=a.tramite_id
 LEFT JOIN usuario u ON u.id=a.usuario_id LEFT JOIN interviniente_documental i ON i.id=a.interviniente_id;
COMMIT;


-- FUENTE: final/30_privilegios_postgres.sql
-- Rol técnico de ejecución; NO es un quinto perfil de personas del portal.
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='yakukhipu_final_api') THEN
  CREATE ROLE yakukhipu_final_api NOLOGIN;
 END IF;
END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA seguridad FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA seguridad FROM PUBLIC;
GRANT CONNECT ON DATABASE yakukhipu_final TO yakukhipu_final_api;
GRANT USAGE ON SCHEMA public,seguridad TO yakukhipu_final_api;
GRANT SELECT ON ALL TABLES IN SCHEMA public,seguridad TO yakukhipu_final_api;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA seguridad TO yakukhipu_final_api;
GRANT INSERT,UPDATE ON seguridad.sesion,seguridad.intento_acceso TO yakukhipu_final_api;
GRANT INSERT ON seguridad.evento_acceso TO yakukhipu_final_api;
GRANT INSERT,UPDATE,DELETE ON tramite,documento,fragmento,publicacion,documento_recibido,alerta,
 conversacion,mensaje,respuesta_cache,fuente,lote_importacion,registro_fuente,encargo
 TO yakukhipu_final_api;
GRANT INSERT ON actuacion,encargo_evento TO yakukhipu_final_api;
GRANT INSERT,UPDATE ON asignacion_tramite TO yakukhipu_final_api;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public,seguridad TO yakukhipu_final_api;
-- No concede DDL ni modificación de usuario, rol o rol_permiso; tampoco UPDATE/DELETE del historial.
-- Crear aparte una cuenta LOGIN con contraseña propia y concederle este rol.

BEGIN;
ALTER TABLE usuario DROP CONSTRAINT usuario_activo_con_credencial;
CREATE TABLE seguridad.identidad_oidc (
 issuer text NOT NULL, subject text NOT NULL, usuario_id varchar(80) NOT NULL REFERENCES usuario(id),
 PRIMARY KEY(issuer, subject), CHECK(length(issuer)>0 AND length(subject)>0)
);
CREATE TABLE seguridad.oidc_transaccion (
 estado_hash varchar(64) PRIMARY KEY, navegador_hash varchar(64) NOT NULL,
 nonce text NOT NULL, verifier text NOT NULL, vence timestamptz NOT NULL DEFAULT now()+interval '10 minutes'
);
CREATE INDEX oidc_transaccion_vence ON seguridad.oidc_transaccion(vence);
CREATE TABLE procesamiento_pdf (
 recepcion_id text PRIMARY KEY REFERENCES documento_recibido(id), clave text NOT NULL UNIQUE,
 sha256 varchar(64) NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 20971520),
 estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','procesando','listo','fallido')),
 intentos integer NOT NULL DEFAULT 0 CHECK(intentos >= 0), tomado timestamptz,
 creado timestamptz NOT NULL DEFAULT now(), paginas jsonb, error text,
 CHECK((estado='listo') = (paginas IS NOT NULL))
);
CREATE INDEX procesamiento_pdf_cola ON procesamiento_pdf(creado) WHERE estado IN ('pendiente','procesando');
CREATE TABLE propuesta_agente (
 documento_id varchar(120) PRIMARY KEY REFERENCES documento(id),
 tramite_id varchar(80) NOT NULL REFERENCES tramite(id),
 estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','procesando','lista','sin_evidencia','fallida','aceptada','rechazada')),
 intentos integer NOT NULL DEFAULT 0 CHECK(intentos>=0),
 tomada timestamptz, creada timestamptz NOT NULL DEFAULT now(), actualizada timestamptz NOT NULL DEFAULT now(),
 propuesta text, fuentes jsonb NOT NULL DEFAULT '[]'::jsonb, advertencias jsonb NOT NULL DEFAULT '[]'::jsonb,
 modelo text, error text, revisada_por varchar(80) REFERENCES usuario(id), revision_motivo text, revisada_en timestamptz,
 CHECK ((estado IN ('lista','aceptada','rechazada')) = (propuesta IS NOT NULL)),
 CHECK ((revisada_en IS NOT NULL) = (estado IN ('aceptada','rechazada')))
);
CREATE INDEX propuesta_agente_cola ON propuesta_agente(creada) WHERE estado IN ('pendiente','procesando');
GRANT SELECT ON seguridad.identidad_oidc TO yakukhipu_final_api;
GRANT SELECT,INSERT,DELETE ON seguridad.oidc_transaccion TO yakukhipu_final_api;
GRANT SELECT,INSERT,UPDATE ON procesamiento_pdf TO yakukhipu_final_api;
GRANT SELECT,INSERT,UPDATE ON propuesta_agente TO yakukhipu_final_api;
COMMIT;

